node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';
import { webcrypto } from 'node:crypto';

const results = [];
for (const format of ['esm', 'iife']) {
  const reads = [], requests = [], writes = [];
  const store = new Map(), jar = new Map([['opt_tracking_consent', 'false'], ['opt_personalization_enabled', 'false']]);
  const state = { tracking: false, personalization: false };
  const layer = [{ get event() { reads.push('replay'); return 'purchase'; } }];
  const document = {
    get cookie() { return [...jar].map(([k, v]) => k + '=' + v).join('; '); },
    set cookie(value) { const [pair] = value.split(';'); const at = pair.indexOf('='); const k = pair.slice(0, at), v = pair.slice(at + 1); if (value.includes('Max-Age=0')) jar.delete(k); else jar.set(k, v); },
    get referrer() { reads.push('referrer'); return 'https://synthetic.invalid/referrer'; },
    querySelectorAll() { reads.push('dom'); return []; },
    addEventListener() {},
  };
  const location = {
    protocol: 'https:', host: 'synthetic.invalid', hostname: 'synthetic.invalid',
    get href() { reads.push('href'); return 'https://synthetic.invalid/private'; },
    get search() { reads.push('search'); return '?utm_source=synthetic'; },
  };
  const fetch = async (url, init) => {
    const path = new URL(url).pathname, body = init?.body ? JSON.parse(init.body) : undefined;
    requests.push({ path, url, body });
    let response;
    if (path.endsWith('/identity/session')) {
      const iat = Math.floor(Date.now() / 1000);
      response = { ok: true, session: { tenant: 'meridian', subject: 'vis-synthetic', sessionId: 's-synthetic', kind: 'anonymous', capability: 'ss1.AA.AA', iat, exp: iat + 3600, consent: { ...state } } };
    } else if (path.endsWith('/preferences')) {
      if (typeof body.trackingConsent === 'boolean') state.tracking = body.trackingConsent;
      if (typeof body.personalizationEnabled === 'boolean') state.personalization = body.personalizationEnabled;
      response = { success: true, sessionId: 's-synthetic', preferences: { trackingConsent: state.tracking, personalizationEnabled: state.personalization } };
    } else if (path.endsWith('/snapshot')) {
      response = { ok: true, page: 'home', arm: 'default', decisions: [], sources: { consent: { ...state } } };
    } else response = { success: true, consent: { ...state }, update: { data: { segments: ['synthetic'] } } };
    return { ok: true, status: 200, json: async () => response };
  };
  const bindings = {
    document, location, fetch, dataLayer: layer, crypto: webcrypto,
    localStorage: { getItem: k => store.get(k) ?? null, setItem: (k, v) => { writes.push(k); store.set(k, v); } },
    navigator: {}, WebSocket: undefined, Date, URL, URLSearchParams,
    setTimeout, clearTimeout, setInterval, clearInterval, addEventListener() {},
  };
  let sdk;
  if (format === 'esm') {
    for (const [key, value] of Object.entries(bindings)) Object.defineProperty(globalThis, key, { value, writable: true, configurable: true });
    sdk = await import('data:text/javascript;base64,' + readFileSync('public/sdk/edge-personalization.esm.js').toString('base64'));
  } else {
    const context = vm.createContext(bindings);
    vm.runInContext(readFileSync('public/sdk/edge-personalization.js', 'utf8'), context);
    sdk = context.EdgePersonalization;
  }
  const client = sdk.createClient({ tenant: 'meridian' });
  assert.deepEqual(reads, []);
  const payload = { get orderId() { reads.push('payload'); return 'synthetic-order'; }, value: 1 };
  await client.emit.purchase(payload);
  assert.equal(requests.length, 0);
  assert.equal(await client.core.ready(), true);
  await client.emit.purchase(payload); await client.emit.pageView(payload);
  client.emit.dataLayer(); client.emit.declarative(); client.emit.rendered('hero', 'synthetic');
  let defaults = 0; client.listen.subscribe('hero', () => { defaults++; client.emit.rendered('hero', 'synthetic'); });
  assert.ok(await client.listen.hydrate({ page: 'home', channel: 'must-omit' }));
  assert.deepEqual(reads, []);
  assert.equal(writes.filter(k => k === 'opt_session').length, 0);
  assert.equal(requests.filter(r => r.path === '/realtime/action').length, 0);
  const snapshot = new URL(requests.find(r => r.path.endsWith('/snapshot')).url);
  assert.equal(snapshot.searchParams.get('trackingConsent'), 'false');
  assert.equal(snapshot.searchParams.has('channel'), false);
  assert.equal(snapshot.searchParams.has('browsingSessionId'), false);
  const refusal = { reads: reads.length, actions: 0, attributionWrites: 0, defaults };
  assert.equal((await client.core.postJson('/realtime/session/s-synthetic/preferences', { trackingConsent: true, personalizationEnabled: true })).ok, true);
  await client.emit.purchase(payload);
  assert.equal(requests.filter(r => r.path === '/realtime/action').length, 1);
  assert.equal(reads.filter(v => v === 'payload').length, 1);
  assert.equal(reads.includes('replay'), false);
  assert.equal(reads.includes('search'), true); assert.equal(reads.includes('referrer'), true);
  results.push({ format, refused: refusal, positiveActions: 1, positivePayloadReads: 1, refusedReplayReads: 0 });
  client.disconnect();
}
console.log(JSON.stringify({ check: 'W05.06 actual built entrypoint smoke', results }, null, 2));
NODE

node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
const sha = value => createHash('sha256').update(value).digest('hex');
const before = JSON.parse(readFileSync('docs/remediation/evidence/W05.06/before-sources-v1.json', 'utf8'));
const files = before.files.map(file => {
  assert.equal(sha(file.content), file.sha256);
  const content = readFileSync(file.path);
  return { path: file.path, before_sha256: file.sha256, sha256: sha(content), bytes: content.length, changed: sha(content) !== file.sha256 };
});
execFileSync('git', ['diff', '--check', '--', ...files.map(f => f.path)], { encoding: 'utf8' });
console.log(JSON.stringify({ scopedDiffCheck: 'pass', retainedOriginals: 'verified', files, digest: sha(files.map(f => f.path + ':' + f.sha256).join('\n')) }, null, 2));
